{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
        {
            "@type": "Question",
            "name": "Which Locations Does ARIID Build & Remodel Serve?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "We proudly serve the communities of Kirkland, Bellevue, and Mercer Island, offering top-notch services tailored to meet the unique needs of each area."
            }
        },
        {
            "@type": "Question",
            "name": "Is a Building a New House Worth It?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Building a new house offers the opportunity to create a space tailored to your specific needs, preferences, and dreams."
            }
        },
        {
            "@type": "Question",
            "name": "What is the Most Expensive Part of Building a House?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "The most expensive part of building a house is often the labor costs. This is because there are many skilled workers involved in the construction process, including carpenters, electricians, plumbers, and painters."
            }
        },
        {
            "@type": "Question",
            "name": "Is it Cheaper to Build New or Buy?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Buying an existing home in Kirkland may be less expensive upfront, but renovation costs can add up. Building a new home generally involves higher initial costs but offers customization and potentially lower maintenance expenses."
            }
        },
        {
            "@type": "Question",
            "name": "How Long Does a New Build Take?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "While the time-frame for building a new home is heavily dependent on the size of the home, generally it may take from 7-12 months. Schedule a consultation with us to get a better idea of how long it may take."
            }
        },
        {
            "@type": "Question",
            "name": "How Do I Get Started With My New Build Project?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Schedule a free consultation with us today to explore how we can assist you. Discover tailored solutions and expert guidance to meet your needs."
            }
        },
        {
            "@type": "Question",
            "name": "What does design-build mean for new home construction?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "In a design-build new construction project, your architecture and design team and your general contractor are the same organization. ARIID handles site analysis, architectural design, engineering coordination, permit submission, and construction under one contract with one project manager. This eliminates the most common failure point in custom home projects — design decisions made without full awareness of construction cost and schedule implications. At ARIID, the design is calibrated to the budget from day one because the designers and builders are the same team."
            }
        },
        {
            "@type": "Question",
            "name": "What types of custom home projects does ARIID Build handle?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "ARIID builds custom homes on infill lots in Kirkland and Bellevue, teardown-rebuild projects on established Eastside lots, and new construction on vacant land throughout King County. We work with homeowners building their long-term primary residence, investment properties, and estate-scale homes in communities like Yarrow Point, Clyde Hill, and Mercer Island. Every project is designed from the site and client program outward — we do not work from stock plans."
            }
        },
        {
            "@type": "Question",
            "name": "How long does a design-build custom home take from start to finish?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "A design-build custom home on the Eastside typically takes 14 to 20 months from initial design kick-off to certificate of occupancy. Design and permitting run 4 to 6 months depending on project complexity and jurisdiction. Construction typically runs 10 to 14 months depending on square footage, site conditions, and finish level. ARIID builds detailed project schedules at design kick-off and maintains weekly construction communication throughout the build."
            }
        }
    ]
}

