{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How much does a bathroom remodel cost?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "A primary bathroom remodel on the Eastside typically ranges from $45,000 to $120,000+ depending on square footage, plumbing relocation, structural work, and finish level. A guest bathroom typically runs $25,000–$55,000. Primary suite bathrooms with custom tile, steam, heated floors, and frameless glass typically run $75,000–$150,000. ARIID provides detailed cost estimates after a site visit."
      }
    },
    {
      "@type": "Question",
      "name": "How long does a bathroom remodeling project typically take?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "A bathroom remodel with ARIID typically runs 8 to 14 weeks from design kick-off to final walkthrough. Design and permitting take 3 to 5 weeks. Construction runs 4 to 8 weeks depending on scope, tile complexity, and fixture lead times. Custom shower glass and specialty tile are ordered before demolition begins to keep the construction phase on schedule."
      }
    },
    {
      "@type": "Question",
      "name": "Do I need to obtain permits for my bathroom remodeling?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, bathroom remodels involving plumbing rough-in changes, new or relocated ventilation, electrical panel work, or structural modifications require building permits. A cosmetic update — new tile over existing substrate, fixture replacement, vanity swap — typically does not. ARIID assesses permit requirements at the initial project meeting and manages the complete permit process within our design-build scope."
      }
    },
    {
      "@type": "Question",
      "name": "What type of warranties do you offer on your bathroom remodeling services?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "We guarantee the calibre of our materials and workmanship. We provide warranties for both labour and materials so you can feel secure knowing your money is well-protected. Your project documentation will include specific warranty information."
      }
    }
  ]
