{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How long does Home additions project typically take?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Home addition projects can take several months to complete, depending on the project's scope and complexity. Factors such as permit approval, weather delays, and unexpected issues can significantly affect timelines."
      }
    },
    {
      "@type": "Question",
      "name": "Do you offer maintenance services for home additions?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "At this time, we do not offer home addition maintenance services. Please note that our focus is on new home construction and renovations. We take great pride in our work and strive to provide the highest quality services to our clients."
      }
    },
    {
      "@type": "Question",
      "name": "What is the most expensive part of home additions?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The most expensive part of home additions is, similar to new builds, labor costs. These costs can vary greatly depending on the complexity of the project, materials used, and location."
      }
    },
    {
      "@type": "Question",
      "name": "What types of home additions does ARIID Build design and build?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "ARIID designs and builds the full range of residential home additions: room additions (primary suite additions, great room expansions, sunroom enclosures), second-story additions over existing footprints, ADU construction (detached, attached, and garage conversion ADUs), and bump-out additions that expand kitchen or bathroom footprints. We are a licensed Washington State general contractor and manage every phase — design, structural engineering coordination, permitting, and construction — under one contract."
      }
    },
    {
      "@type": "Question",
      "name": "How long does a home addition take from start to finish?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "A typical room addition on the Eastside takes 4 to 6 months from permit submittal to completion. Design and permitting typically run 6 to 10 weeks depending on jurisdiction and project complexity. Construction of a room addition runs 8 to 14 weeks depending on scope and finish level. Second-story additions and ADU projects run longer — typically 6 to 9 months total. ARIID builds realistic schedules at project intake and manages the timeline through every phase."
      }
    },
    {
      "@type": "Question",
      "name": "Does ARIID handle the full permit process for home additions?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes — ARIID manages the complete permit process for every addition project. We prepare architectural drawings, coordinate structural engineering, compile energy code compliance documentation, and submit complete permit packages to the applicable jurisdiction — City of Kirkland, City of Bellevue, City of Sammamish, City of Issaquah, City of Mercer Island, King County, or City of Seattle. We manage plan review correspondence and schedule all required inspections. Homeowners do not need to interact with the building department at any point."
      }
    }
  ]
